console.log("Privacy Browser Agent Service Worker initialized.");chrome.runtime.onInstalled.addListener(()=>{console.log("Privacy Browser Agent installed successfully.")});chrome.runtime.onMessage.addListener((t,i,r)=>{if(t.type==="CAPTURE_SCREENSHOT"){try{chrome.tabs.captureVisibleTab(null,{format:"jpeg",quality:80},e=>{var s;chrome.runtime.lastError||!e?r({success:!1,error:((s=chrome.runtime.lastError)==null?void 0:s.message)||"Failed to capture visible tab."}):r({success:!0,dataUrl:e})})}catch(e){r({success:!1,error:e.message||"Error executing captureVisibleTab"})}return!0}});
